def main():
    changed = {}
    for topic, mid, start, intro, keys in K:
        p = ROOT / f'{topic}.md'
        lines = changed.get(topic) or p.read_text(encoding='utf-8').split('\n')
        # find the lesson, then the formula block whose first line starts with `start`
        try:
            s = lines.index(f'# {mid}')
        except ValueError:
            sys.exit(f'lesson {mid} not found in {topic}')
        end = next((k for k in range(s + 1, len(lines)) if lines[k].startswith('# v')), len(lines))
        hit = None
        for k in range(s, end - 1):
            if lines[k].startswith('```') and lines[k + 1].strip().startswith(start):
                hit = k; break
        if hit is None:
            sys.exit(f'formula "{start}" not found in {topic} {mid}')
        close = next(k for k in range(hit + 1, end) if lines[k].startswith('```'))
        if close + 1 < len(lines) and lines[close + 1].startswith('~ '):
            continue  # already keyed
        lines[close + 1:close + 1] = [f'~ {x}' for x in keys]
        if intro:
            lines[hit:hit] = [intro, '']
        changed[topic] = lines
    for topic, lines in changed.items():
        (ROOT / f'{topic}.md').write_text('\n'.join(lines), encoding='utf-8')
    print('keyed formulas in', sorted(changed), sum(1 for x in K), 'entries')


if __name__ == '__main__':
    main()
